/* jslint white: true */

function BCRASelectedCalculator() {
    var self = this;

    this.constants = function(group) {
        if (group === "US Hispanic") {
            return {
                lambda1: [
                    0.0000166, 0.0000741, 0.0002740, 0.0006099,
                    0.0012225, 0.0019027, 0.0023142, 0.0028357,
                    0.0031144, 0.0030794, 0.0033344, 0.0035082,
                    0.0025308, 0.0020414
                ],
                lambda2: [
                    0.0003561, 0.0004038, 0.0005281, 0.0008875,
                    0.0013987, 0.0020769, 0.0030912, 0.0046960,
                    0.0076050, 0.0120555, 0.0193805, 0.0288386,
                    0.0429634, 0.0740349
                ],
                oneMinusARBelow50: 0.749294788397,
                oneMinusARAbove50: 0.778215491668,
                beta: {
                    biopsy: 0.0970783641,
                    menarche: 0.0000000000,
                    firstBirth: 0.2318368334,
                    relatives: 0.166685441,
                    biopsyAgeInteraction: 0.0000000000,
                    birthRelativesInteraction: 0.0000000000
                }
            };
        } else if (group === "Foreign Hispanic") {
            return {
                lambda1: [
                    0.0000102, 0.0000531, 0.0001578, 0.0003602,
                    0.0007617, 0.0011599, 0.0014111, 0.0017245,
                    0.0020619, 0.0023603, 0.0025575, 0.0028227,
                    0.0028295, 0.0025868
                ],
                lambda2: [
                    0.0003129, 0.0002908, 0.0003515, 0.0004943,
                    0.0007807, 0.0012840, 0.0020325, 0.0034533,
                    0.0058674, 0.0096888, 0.0154429, 0.0254675,
                    0.0448037, 0.1125678
                ],
                oneMinusARBelow50: 0.428864989813,
                oneMinusARAbove50: 0.450352338746,
                beta: {
                    biopsy: 0.4798624017,
                    menarche: 0.2593922322,
                    firstBirth: 0.4669246218,
                    relatives: 0.9076679727,
                    biopsyAgeInteraction: 0.0000000000,
                    birthRelativesInteraction: 0.0000000000
                }
            };
        } else if (group === "Other Asian") {
            return {
                lambda1: [
                    0.000012355409, 0.000059526456, 0.000184320831,
                    0.000454677273, 0.000791265338, 0.001048462801,
                    0.001372467817, 0.001495473711, 0.001646746198,
                    0.001478363563, 0.001216010125, 0.001067663700,
                    0.001376104012, 0.000661576644
                ],
                lambda2: [
                    0.000212632332, 0.000242170741, 0.000301552711,
                    0.000369053354, 0.000543002943, 0.000893862331,
                    0.001515172239, 0.002574669551, 0.004324370426,
                    0.007419621918, 0.013251765130, 0.022291427490,
                    0.041746550635, 0.087485802065
                ],
                oneMinusARBelow50: 0.47519806426735,
                oneMinusARAbove50: 0.50316401683903,
                beta: {
                    biopsy: 0.55263612260619,
                    menarche: 0.07499257592975,
                    firstBirth: 0.27638268294593,
                    relatives: 0.79185633720481,
                    biopsyAgeInteraction: 0.0000000000,
                    birthRelativesInteraction: 0.0000000000
                }
            };
        }

        throw "Invalid selected BCRA group.";
    };

    this.expandRates = function(rate14) {
        var out = [];
        var i, j;

        for (i = 0; i < rate14.length; i++) {
            for (j = 0; j < 5; j++) {
                out.push(rate14[i]);
            }
        }

        return out;
    };

    this.recode = function(group, age, nBiopsies, hyperplasia, menarcheAge, firstBirthAge, nRelatives) {
        var NB_Cat, AM_Cat, AF_Cat, NR_Cat, R_Hyp;

        if (isNaN(nBiopsies) || nBiopsies === 99 || nBiopsies === 0) {
            NB_Cat = 0;
        } else if (nBiopsies === 1) {
            NB_Cat = 1;
        } else if (nBiopsies >= 2) {
            NB_Cat = 2;
        } else {
            NB_Cat = 0;
        }

        if ((group === "US Hispanic" || group === "Foreign Hispanic") && NB_Cat === 2) {
            NB_Cat = 1;
        }

        if (NB_Cat === 0) {
            R_Hyp = 1.00;
        } else if (hyperplasia === 1) {
            R_Hyp = 1.82;
        } else if (hyperplasia === 0) {
            R_Hyp = 0.93;
        } else {
            R_Hyp = 1.00;
        }

        if (isNaN(menarcheAge) || menarcheAge === 99 || menarcheAge >= 14) {
            AM_Cat = 0;
        } else if (menarcheAge >= 12 && menarcheAge < 14) {
            AM_Cat = 1;
        } else if (menarcheAge > 0 && menarcheAge < 12) {
            AM_Cat = 2;
        } else {
            AM_Cat = 0;
        }

        if (group === "US Hispanic") {
            AM_Cat = 0;
        }

        if (firstBirthAge === 0) {
            AF_Cat = 2;
        } else if (isNaN(firstBirthAge) || firstBirthAge === 99 || firstBirthAge < 20) {
            AF_Cat = 0;
        } else if (firstBirthAge >= 20 && firstBirthAge < 25) {
            AF_Cat = 1;
        } else if (firstBirthAge >= 25 && firstBirthAge < 30) {
            AF_Cat = 2;
        } else if (firstBirthAge >= 30) {
            AF_Cat = 3;
        } else {
            AF_Cat = 0;
        }

        if (group === "US Hispanic" || group === "Foreign Hispanic") {
            if (firstBirthAge !== 0 && AF_Cat === 2) {
                AF_Cat = 1;
            }

            if (AF_Cat === 3) {
                AF_Cat = 2;
            }
        }

        if (isNaN(nRelatives) || nRelatives === 99 || nRelatives === 0) {
            NR_Cat = 0;
        } else if (nRelatives === 1) {
            NR_Cat = 1;
        } else if (nRelatives >= 2) {
            NR_Cat = 2;
        } else {
            NR_Cat = 0;
        }

        if ((group === "US Hispanic" || group === "Foreign Hispanic" || group === "Other Asian") && NR_Cat === 2) {
            NR_Cat = 1;
        }

        return {
            NB_Cat: NB_Cat,
            AM_Cat: AM_Cat,
            AF_Cat: AF_Cat,
            NR_Cat: NR_Cat,
            R_Hyp: R_Hyp
        };
    };

    this.relativeRisk = function(group, age, nBiopsies, hyperplasia, menarcheAge, firstBirthAge, nRelatives) {
        var c = self.constants(group);
        var b = c.beta;
        var r = self.recode(group, age, nBiopsies, hyperplasia, menarcheAge, firstBirthAge, nRelatives);

        var LP1 =
            r.NB_Cat * b.biopsy +
            r.AM_Cat * b.menarche +
            r.AF_Cat * b.firstBirth +
            r.NR_Cat * b.relatives +
            r.AF_Cat * r.NR_Cat * b.birthRelativesInteraction +
            Math.log(r.R_Hyp);

        var LP2 = LP1 + r.NB_Cat * b.biopsyAgeInteraction;

        return {
            RRBefore50: Math.exp(LP1),
            RRAfter50: Math.exp(LP2),
            recoded: r
        };
    };

    this.absoluteRisk = function(group, T1, T2, nBiopsies, hyperplasia, menarcheAge, firstBirthAge, nRelatives, average) {
        if (T1 < 20 || T1 >= 90) {
            throw "T1 must be >=20 and <90.";
        }

        if (T2 > 90) {
            throw "T2 must be <=90.";
        }

        if (T2 <= T1) {
            throw "T2 must be greater than T1.";
        }

        var c = self.constants(group);
        var lambda1 = self.expandRates(c.lambda1);
        var lambda2 = self.expandRates(c.lambda2);
        var oneARRR = [];
        var rr, i;

        if (average) {
            for (i = 0; i < 70; i++) {
                oneARRR[i] = 1.0;
            }
        } else {
            rr = self.relativeRisk(group, T1, nBiopsies, hyperplasia, menarcheAge, firstBirthAge, nRelatives);

            for (i = 0; i < 30; i++) {
                oneARRR[i] = c.oneMinusARBelow50 * rr.RRBefore50;
            }

            for (i = 30; i < 70; i++) {
                oneARRR[i] = c.oneMinusARAbove50 * rr.RRAfter50;
            }
        }

        var startInterval = Math.floor(T1) - 20;
        var numberIntervals = Math.ceil(T2) - Math.floor(T1);
        var riskWork = 0.0;
        var cumulativeLambda = 0.0;
        var j, jInterval, intervalLength, z1, z2, lambdaJ, probabilityInterval;

        for (j = 0; j < numberIntervals; j++) {
            jInterval = startInterval + j;

            if (numberIntervals === 1) {
                intervalLength = T2 - T1;
            } else if (j === 0) {
                intervalLength = 1 - (T1 - Math.floor(T1));
            } else if (j === numberIntervals - 1) {
                z1 = (T2 > Math.floor(T2)) ? 1 : 0;
                z2 = (T2 === Math.floor(T2)) ? 1 : 0;
                intervalLength = (T2 - Math.floor(T2)) * z1 + z2;
            } else {
                intervalLength = 1;
            }

            lambdaJ = lambda1[jInterval] * oneARRR[jInterval] + lambda2[jInterval];

            probabilityInterval =
                ((oneARRR[jInterval] * lambda1[jInterval] / lambdaJ) *
                    Math.exp(-cumulativeLambda)) *
                (1 - Math.exp(-lambdaJ * intervalLength));

            riskWork += probabilityInterval;
            cumulativeLambda += lambdaJ * intervalLength;
        }

        return riskWork;
    };

    this.calculate = function(group, currentAge, menarcheAge, firstBirthAge, nBiopsies, hyperplasia, nRelatives) {
        var patient5yr = self.absoluteRisk(group, currentAge, currentAge + 5, nBiopsies, hyperplasia, menarcheAge, firstBirthAge, nRelatives, false);
        var average5yr = self.absoluteRisk(group, currentAge, currentAge + 5, nBiopsies, hyperplasia, menarcheAge, firstBirthAge, nRelatives, true);
        var patientLife = self.absoluteRisk(group, currentAge, 90, nBiopsies, hyperplasia, menarcheAge, firstBirthAge, nRelatives, false);
        var averageLife = self.absoluteRisk(group, currentAge, 90, nBiopsies, hyperplasia, menarcheAge, firstBirthAge, nRelatives, true);

        return {
            patient5yr: patient5yr,
            average5yr: average5yr,
            patientLife: patientLife,
            averageLife: averageLife
        };
    };
}

function GailCalculator(userCurrentAge, userMenarcheAge, userFirstLiveBirthAge, userFirstDegreeRel, userHadBiopsy, userNumBiopsy, userHyperPlasia, userRace, selectedBCRAGroup) {
    var self = this;

    this.BcptConvert = {
        getCurrentAge: function(userCurrentAge) {
            switch (true) {
                case (userCurrentAge > 0 && userCurrentAge < 35):
                    return 34
                case (userCurrentAge <= 0 && userCurrentAge >= 90):
                    return 90
                default:
                    return userCurrentAge
            }
        },
        getMenarcheAge: function(userMenarcheAge) {
            switch (userMenarcheAge) {
                case 0:
                    return 99
                case 1:
                    return 10
                case 2:
                    return 13
                case 3:
                    return 14
            }
        },
        getFirstLiveBirthAge: function(userFirstLiveBirthAge) {
            switch (userFirstLiveBirthAge) {
                case 0:
                    return 0
                case 1:
                    return 15
                case 2:
                    return 22
                case 3:
                    return 27
                case 4:
                    return 31
                case 5:
                    return 99
            }
        },
        getFirstDegRelatives: function(userFirstDegreeRel) {
            switch (userFirstDegreeRel) {
                case 0:
                    return 99
                case 1:
                    return 0
                case 2:
                    return 1
                case 3:
                    return 2
            }
        },
        getEverHadBiopsy: function(userHadBiopsy) {
            switch (userHadBiopsy) {
                case 0:
                    return 99
                case 1:
                    return 0
                case 2:
                    return 1
            }
        },
        getNumberOfBiopsy: function(userNumBiopsy) {
            switch (userNumBiopsy) {
                case 1:
                    return 1
                case 2:
                    return 2
            }
        },
        getHyperPlasia: function(userHyperPlasia) {
            switch (userHyperPlasia) {
                case 0:
                    return 99
                case 1:
                    return 0
                case 2:
                    return 1
            }
        },
        getRace: function(userRace) {
            switch (userRace) {
                case 0:
                    return 1
                case 1:
                    return 2
                case 2:
                    return 3
                case 3:
                    return 7
                case 4:
                    return 8
                case 5:
                    return 9
                case 6:
                    return 10
                case 7:
                    return 11
                case 8:
                    return 12
                case 9:
                    return 1
                default:
                    return 1
            }
        },
        menarcheAge: function(menarcheAge) {
            switch (true) {
                case (menarcheAge >= 7 && menarcheAge < 12):
                    return 2
                case (menarcheAge >= 12 && menarcheAge < 14):
                    return 1
                case (menarcheAge >= 14 && menarcheAge <= 39 || menarcheAge == 99):
                    return 0
                default:
                    return 0
            }
        },
        firstLiveBirthAge: function(firstLiveBirthAge) {
            switch (true) {
                case (firstLiveBirthAge == 0):
                    return 2
                case (firstLiveBirthAge < 20 || firstLiveBirthAge == 99):
                    return 0
                case (firstLiveBirthAge >= 20 && firstLiveBirthAge < 25):
                    return 1
                case (firstLiveBirthAge >= 25 && firstLiveBirthAge < 30):
                    return 2
                case (firstLiveBirthAge >= 30 && firstLiveBirthAge <= 55):
                    return 3
                default:
                    return 0
            }
        },
        everHadBiopsy: function(everHadBiopsy) {
            switch (everHadBiopsy) {
                case (99):
                    return 0
                default:
                    return everHadBiopsy
            }
        },
        numberOfBiopsy: function(numberOfPreviousBiopsy, everHadBiopsy) {
            switch (true) {
                case (everHadBiopsy == 99):
                    return 99
                case (numberOfPreviousBiopsy == 0 || (numberOfPreviousBiopsy == 99 && everHadBiopsy == 99)):
                    return 0
                case (numberOfPreviousBiopsy == 1 || (numberOfPreviousBiopsy == 99 && everHadBiopsy == 1)):
                    return 1
                case (numberOfPreviousBiopsy > 1 && numberOfPreviousBiopsy <= 30):
                    return 2
                default:
                    return 0
            }
        },
        hyperplasia: function(hyperPlasia, everHadBiopsy) {
            switch (true) {
                case (everHadBiopsy == 0):
                    return 99
                default:
                    return hyperPlasia
            }
        },
        firstDegRelatives: function(firstDegRelatives, race) {
            if (race == undefined) {
                switch (true) {
                    case (firstDegRelatives == 0 || firstDegRelatives == 99):
                        return 0
                    case (firstDegRelatives == 1):
                        return 1
                    case (firstDegRelatives >= 2 && firstDegRelatives <= 31):
                        return 2
                    default:
                        return 0
                }
            } else {
                switch (true) {
                    case (firstDegRelatives == 0 || firstDegRelatives == 99):
                        return 0
                    case (firstDegRelatives == 1):
                        return 1
                    case (firstDegRelatives >= 2 && firstDegRelatives <= 31 && race < 7):
                        return 2
                    case (firstDegRelatives >= 2 && race >= 7):
                        return 1
                    default:
                        return 0
                }
            }
        },
        currentAgeIndicator: function(currentAge) {
            switch (true) {
                case (currentAge < 50):
                    return 0
                case (currentAge >= 50):
                    return 1
                default:
                    return 0
            }
        },
        rHyperplasia: function(hyperplasia, everHadBiopsy) {
            switch (hyperplasia) {
                case 1:
                    return 1.82;
                case 0:
                    return 0.93;
                default:
                    return 1.0;
            }
        }
    };

    this.RiskCalculator = {
        calculateRisk: function(riskindex, currentAge, projectionAge, ageIndicator, numberOfBiopsy, menarcheAge, firstLiveBirthAge, firstDegRelatives, everHadBiopsy, ihyp, rhyp, irace) {

            var numCovPattInGailModel = 216
            var bet2 = self.InitiateRickCalculatorVars.bet2(8, 12)
            var t = self.InitiateRickCalculatorVars.t(15)
            var rmu2 = self.InitiateRickCalculatorVars.rmu2(14, 12)
            var rlan2 = self.InitiateRickCalculatorVars.rlan2(14, 12)
            var rf2 = self.InitiateRickCalculatorVars.rf2(2, 13)

            var bet = []
            var rf = []
            var abs = []
            var rlan = []
            var rmu = []
            var sumb = []
            var sumbb = []

            var retval = 0.0;
            var i
            var j
            var k
            var n = 216
            var r = 0.0
            var ni = 0
            var ti = currentAge
            var ns = 0
            var ts = projectionAge
            var abss = 0.0
            var incr
            var ilev
            var cindx
            var r8iTox2 = self.Conveniences.createTwoDimensionArray(216, 9)

            for (i = 0; i < 8; i++) {
                bet[i] = bet2[i][irace - 1];
            }

            if (irace == 2) {
                if (menarcheAge == 2) {
                    menarcheAge = 1;
                    firstLiveBirthAge = 0;
                }
            }

            for (i = 1; i <= 15; ++i) {
                if (ti < t[i - 1]) {
                    ni = i - 1;
                    break;
                }
            }

            for (i = 1; i <= 15; ++i) {
                if (ts <= t[i - 1]) {
                    ns = i - 1
                    break;
                }
            }

            incr = 0;

            if (riskindex == 2 && irace < 7) {
                incr = 3;
            }

            cindx = incr + irace - 1;

            for (i = 0; i < 14; ++i) {
                rmu[i] = rmu2[i][cindx];
                rlan[i] = rlan2[i][cindx];
            }

            rf[0] = rf2[0][incr + irace - 1];
            rf[1] = rf2[1][incr + irace - 1];

            if (riskindex == 2 && irace >= 7) {
                rf[0] = rf2[0][12];
                rf[1] = rf2[1][12];
            }

            if (riskindex >= 2) {
                menarcheAge = 0;
                numberOfBiopsy = 0;
                firstLiveBirthAge = 0;
                firstDegRelatives = 0;
                rhyp = 1.0;
            }

            ilev = ageIndicator * 108 + menarcheAge * 36 + numberOfBiopsy * 12 + firstLiveBirthAge * 3 + firstDegRelatives + 1;

            for (k = 0; k < 216; ++k) {
                r8iTox2[k][0] = 1.0;
            }

            for (k = 0; k < 108; ++k) {
                r8iTox2[k][1] = 0.0;
                r8iTox2[108 + k][1] = 1.0;
            }

            for (j = 1; j <= 2; ++j) {
                for (k = 1; k <= 36; ++k) {
                    r8iTox2[(j - 1) * 108 + k - 1][2] = 0.0;
                    r8iTox2[(j - 1) * 108 + 36 + k - 1][2] = 1.0;
                    r8iTox2[(j - 1) * 108 + 72 + k - 1][2] = 2.0;
                }
            }

            for (j = 1; j <= 6; ++j) {
                for (k = 1; k <= 12; ++k) {
                    r8iTox2[(j - 1) * 36 + k - 1][3] = 0.0;
                    r8iTox2[(j - 1) * 36 + 12 + k - 1][3] = 1.0;
                    r8iTox2[(j - 1) * 36 + 24 + k - 1][3] = 2.0;
                }
            }

            for (j = 1; j <= 18; ++j) {
                for (k = 1; k <= 3; ++k) {
                    r8iTox2[(j - 1) * 12 + k - 1][4] = 0.0;
                    r8iTox2[(j - 1) * 12 + 3 + k - 1][4] = 1.0;
                    r8iTox2[(j - 1) * 12 + 6 + k - 1][4] = 2.0;
                    r8iTox2[(j - 1) * 12 + 9 + k - 1][4] = 3.0;
                }
            }

            for (j = 1; j <= 72; ++j) {
                r8iTox2[(j - 1) * 3][5] = 0.0;
                r8iTox2[(j - 1) * 3 + 1][5] = 1.0;
                r8iTox2[(j - 1) * 3 + 2][5] = 2.0;
            }

            for (i = 0; i < 216; ++i) {
                r8iTox2[i][6] = r8iTox2[i][1] * r8iTox2[i][3];
                r8iTox2[i][7] = r8iTox2[i][4] * r8iTox2[i][5];
            }

            for (i = 0; i < 216; ++i) {
                r8iTox2[i][8] = 1.0;
            }

            for (i = 0; i < 216; ++i) {
                sumb[i] = 0.0;
                for (j = 0; j < 8; ++j) {
                    sumb[i] += bet[j] * r8iTox2[i][j];
                }
            }

            for (i = 1; i <= 108; ++i) {
                sumbb[i - 1] = sumb[i - 1] - bet[0];
            }

            for (i = 109; i <= 216; ++i) {
                sumbb[i - 1] = sumb[i - 1] - bet[0] - bet[1];
            }

            for (j = 1; j <= 6; ++j) {
                rlan[j - 1] = rlan[j - 1] * rf[0];
            }

            for (j = 7; j <= 14; ++j) {
                rlan[j - 1] = rlan[j - 1] * rf[1];
            }

            i = ilev

            sumbb[i - 1] += Math.log(rhyp);

            if (i <= 108) {
                sumbb[i + 107] += Math.log(rhyp);
            }

            if (ts <= t[ni]) {
                abs[i - 1] = 1.0 - Math.exp(-(rlan[ni - 1] * Math.exp(sumbb[i - 1]) + rmu[ni - 1]) * (ts - ti));
                abs[i - 1] = abs[i - 1] * rlan[ni - 1] * Math.exp(sumbb[i - 1]) / (rlan[ni - 1] * Math.exp(sumbb[i - 1]) + rmu[ni - 1]);
            } else {
                abs[i - 1] = 1.0 - Math.exp(-(rlan[ni - 1] * Math.exp(sumbb[i - 1]) + rmu[ni - 1]) * (t[ni] - ti));
                abs[i - 1] = abs[i - 1] * rlan[ni - 1] * Math.exp(sumbb[i - 1]) / (rlan[ni - 1] * Math.exp(sumbb[i - 1]) + rmu[ni - 1]);

                if (ns - ni > 0) {
                    if (projectionAge > 50.0 && currentAge < 50.0) {
                        r = 1.0 - Math.exp(-(rlan[ns - 1] * Math.exp(sumbb[i + 107]) + rmu[ns - 1]) * (ts - t[ns - 1]));
                        r = r * rlan[ns - 1] * Math.exp(sumbb[i + 107]) / (rlan[ns - 1] * Math.exp(sumbb[i + 107]) + rmu[ns - 1]);
                        r = r * Math.exp(-(rlan[ni - 1] * Math.exp(sumbb[i - 1]) + rmu[ni - 1]) * (t[ni] - ti));

                        if (ns - ni > 1) {
                            menarcheAge = ns - 1;
                            for (j = ni + 1; j <= menarcheAge; ++j) {
                                if (t[j - 1] >= 50.0) {
                                    r = r * Math.exp(-(rlan[j - 1] * Math.exp(sumbb[i + 107]) + rmu[j - 1]) * (t[j] - t[j - 1]));
                                } else {
                                    r = r * Math.exp(-(rlan[j - 1] * Math.exp(sumbb[i - 1]) + rmu[j - 1]) * (t[j] - t[j - 1]));
                                }
                            }
                        }

                        abs[i - 1] += r;
                    } else {
                        r = 1.0 - Math.exp(-(rlan[ns - 1] * Math.exp(sumbb[i - 1]) + rmu[ns - 1]) * (ts - t[ns - 1]));
                        r = r * rlan[ns - 1] * Math.exp(sumbb[i - 1]) / (rlan[ns - 1] * Math.exp(sumbb[i - 1]) + rmu[ns - 1]);
                        r = r * Math.exp(-(rlan[ni - 1] * Math.exp(sumbb[i - 1]) + rmu[ni - 1]) * (t[ni] - ti));

                        if (ns - ni > 1) {
                            menarcheAge = ns - 1;
                            for (j = ni + 1; j <= menarcheAge; ++j) {
                                r = r * Math.exp(-(rlan[j - 1] * Math.exp(sumbb[i - 1]) + rmu[j - 1]) * (t[j] - t[j - 1]));
                            }
                        }

                        abs[i - 1] += r;
                    }
                }

                if (ns - ni > 1) {
                    if (projectionAge > 50.0 && currentAge < 50.0) {
                        menarcheAge = ns - 1

